"use server";

import { getSession } from "@/modules/auth/lib/session";
import { getUser } from "@/lib/user/service";
import { getOrganizationsByUserId } from "@/lib/organization/service";

export type TUserDataExport = {
  name: string;
  email: string;
  locale: string;
  notificationSettings: {
    alert: Record<string, boolean>;
    unsubscribedOrganizationIds: string[] | undefined;
  };
  organizations: Array<{
    name: string;
    role: string;
  }>;
};

export async function downloadUserDataAction(): Promise<TUserDataExport | null> {
  const session = await getSession();
  if (!session?.user) {
    return null;
  }

  const user = await getUser(session.user.id);
  if (!user) {
    return null;
  }

  const organizations = await getOrganizationsByUserId(session.user.id);

  return {
    name: user.name,
    email: user.email,
    locale: user.locale,
    notificationSettings: user.notificationSettings,
    organizations: organizations.map((org) => ({
      name: org.name,
      role: org.memberships?.[0]?.role ?? "member",
    })),
  };
}

"use client";

import React from "react";
import { useTranslation } from "react-i18next";
import { Button } from "@/modules/ui/components/button";
import { downloadUserDataAction, type TUserDataExport } from "../actions";

export function DownloadMyDataButton() {
  const { t } = useTranslation();
  const [isDownloading, setIsDownloading] = React.useState(false);

  const handleDownload = async () => {
    setIsDownloading(true);
    try {
      const data = await downloadUserDataAction();
      if (!data) {
        return;
      }
      const jsonString = JSON.stringify(data, null, 2);
      const blob = new Blob([jsonString], { type: "application/json" });
      const url = URL.createObjectURL(blob);
      const link = document.createElement("a");
      link.href = url;
      link.download = "formbricks-account-data.json";
      document.body.appendChild(link);
      link.click();
      document.body.removeChild(link);
      URL.revokeObjectURL(url);
    } finally {
      setIsDownloading(false);
    }
  };

  return (
    <Button variant="secondary" size="sm" onClick={handleDownload} loading={isDownloading}>
      {t("workspace.settings.profile.download_my_data_button")}
    </Button>
  );
}
